let authSetupAvailable=false;
function authPath(){const path=location.pathname.replace(/^\/+|\/+$/g,'').replace(/\.html$/,'');if(['login','register','forgot-password','reset-password','verify-email'].includes(path))return path;const legacy=location.hash.slice(1);return ['login','register','forgot-password','reset-password','verify-email'].includes(legacy)?legacy:''}
function authRoute(){return Boolean(authPath())}
function togglePassword(id,button){const input=document.getElementById(id);input.type=input.type==='password'?'text':'password';button.textContent=input.type==='password'?'Show':'Hide';button.setAttribute('aria-label',(input.type==='password'?'Show':'Hide')+' password')}
function auth(setup=false,join=''){authSetupAvailable=setup;state=null;authPage(join?'join':authRoute()?authPath():setup?'register':'login',join)}
function authPage(kind='login',join=''){
 if(kind==='reset-password')return resetPage();
 if(kind==='verify-email')return verificationPage();
 stopVoice();if(kind!=='join'){const target='/'+kind;if(location.pathname!==target||location.hash)history.replaceState(null,'',target);document.title=({login:'Log in',register:'Register','forgot-password':'Forgot password'})[kind]+' | Bainbot'}const register=kind==='register'||kind==='join',forgot=kind==='forgot-password';
 const title=forgot?'Forgot your password?':kind==='join'?'Join your team':register?'Build your AI team':'Welcome back';
 const sub=forgot?'Enter your email and we’ll help you get back to work.':register?'One workspace. A team that works together.':'Your team is ready when you are.';
 const passwordField=(id,label,autocomplete)=>`<label for="${id}">${label}</label><div class="auth-password"><input id="${id}" name="${id}" type="password" required minlength="12" maxlength="200" autocomplete="${autocomplete}" placeholder="${id==='confirm'?'Re-enter your password':'Enter your password'}"><button type="button" onclick="togglePassword('${id}',this)" aria-label="Show password">Show</button></div>`;
 $('#app').innerHTML=`<div class="auth-screen"><aside class="auth-story"><a class="auth-logo" href="/login">Bainbot<span class="auth-logo-dot"></span></a><div class="auth-story-content"><span class="auth-eyebrow">YOUR AI TEAM, AT WORK</span><h1>Good work.<br>Better together.</h1><p>Bring marketing, sales, support, and creative work into one calm workspace.</p><div class="auth-team-visual">${[0,3,4].map((n,i)=>`<div class="auth-teammate">${avatar({avatar:n})}<span>${['Plan','Create','Deliver'][i]}</span></div>`).join('')}</div><div class="auth-story-note"><span class="auth-check">✓</span><span>One shared goal.<br><strong>You stay in control.</strong></span></div></div><span class="auth-story-footer">Built for teams with more to do.</span></aside><main class="auth-main"><div class="auth-top"><a href="/login" class="auth-mobile-logo">Bainbot</a><span>${register?'Already have an account?':forgot?'Remember your password?':'New to Bainbot?'}</span><a href="${register||forgot?'/login':'/register'}">${register||forgot?'Log in':'Create an account'} <span aria-hidden="true">↗</span></a></div><section class="auth-panel"><div id="auth-content"><span class="auth-section-label">${forgot?'ACCOUNT RECOVERY':register?'GET STARTED':'YOUR WORKSPACE'}</span><h2>${title}</h2><p class="auth-subtitle">${sub}</p><form id="access-form" class="auth-fields">${register?'<label for="full-name">Full name</label><input id="full-name" name="name" autocomplete="name" placeholder="Your full name" required maxlength="80">':''}<label for="auth-email">Email address</label><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="you@company.com" required maxlength="200">${forgot?'':passwordField('password','Password',register?'new-password':'current-password')}${register?'<p class="auth-field-hint">Use at least 12 characters.</p>'+passwordField('confirm','Confirm password','new-password'):''}${!register&&!forgot?'<a class="auth-forgot" href="/forgot-password">Forgot password?</a><button class="bare" type="button" onclick="resendVerification()">Resend verification email</button>':''}<p id="auth-error" class="auth-error" role="alert"></p><button type="submit" class="auth-submit">${forgot?'Send reset link':kind==='join'?'Join workspace':register?'Create account':'Log in'} <span aria-hidden="true">→</span></button></form><p class="auth-preview-note">${mode==='demo'?'Frontend preview · No account is created, passwords are not saved, and no emails are sent.':forgot?(serverStatus.reset_enabled?'A reset link will be sent if the account exists.':'Email recovery is not configured. Contact your owner.'):register?'Free beta · No credit card required.':'Secure access to your workspace.'}</p><a class="auth-back" href="${forgot?'/login':'/'}">${forgot?'← Back to login':mode==='demo'?'Explore the demo workspace →':'← Back to workspace'}</a></div></section><div class="auth-bottom">Bainbot <span>Thoughtful tools. Meaningful work.</span></div></main></div>`;
 $('#access-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=e.submitter,error=$('#auth-error');error.textContent='';const fields=Object.fromEntries(new FormData(f));if(register&&fields.password!==fields.confirm){error.textContent='Your passwords don’t match.';f.elements.confirm.focus();return}if(register&&!fields.name.trim()){error.textContent='Enter your full name.';return}b.disabled=true;try{
 if(forgot){await api('/forgot-password',{email:fields.email});authFeedback('Check your inbox','If an account matches this email, a reset link has been sent. It expires in 30 minutes.','Back to login','/login');return}
 if(mode==='demo'){f.reset();authFeedback(register?'Your workspace starts here':'Welcome to Bainbot',register?'Registration preview complete. No account was created and your password was not saved.':'Login preview complete. No credentials were checked or saved. You can explore the demo workspace.','Explore demo workspace','/');return}
 delete fields.confirm;if(join)fields.token=join;const result=await api(join?'/invites/accept':register?'/register':'/login',fields);if(result.verification_required){authFeedback('Verify your email','Open the link in your email to activate your account. It expires in 30 minutes.','Back to login','/login');return}state=await api('/state');history.replaceState(null,'','/app');route();
 }catch(err){error.textContent=err.message}finally{b.disabled=false}};
}
function authFeedback(title,message,label,href){$('#auth-content').innerHTML=`<span class="auth-success-symbol" aria-hidden="true">✓</span><h2>${esc(title)}</h2><p class="auth-subtitle">${esc(message)}</p><a class="auth-submit auth-success-link" href="${href}">${esc(label)} →</a>`}

function resetPage(){
 const token=new URLSearchParams(location.search).get('token')||'';
 authPage('forgot-password');history.replaceState(null,'','/reset-password');
 $('#auth-content').innerHTML=`<span class="auth-section-label">ACCOUNT RECOVERY</span><h2>Set a new password</h2><p class="auth-subtitle">Choose a password with at least 12 characters.</p><form id="reset-form" class="auth-fields"><label for="new-password">New password</label><input id="new-password" name="password" type="password" autocomplete="new-password" minlength="12" maxlength="200" required><label for="repeat-password">Confirm password</label><input id="repeat-password" name="confirm" type="password" autocomplete="new-password" minlength="12" maxlength="200" required><p id="reset-error" class="auth-error" role="alert">${token?'':'This link is missing its reset token. Request a new link.'}</p><button class="auth-submit" ${token?'':'disabled'}>Update password →</button></form><a class="auth-back" href="/forgot-password">Request another reset link</a>`;
 $('#reset-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=e.submitter,error=$('#reset-error');error.textContent='';if(f.elements.password.value!==f.elements.confirm.value){error.textContent='Passwords don’t match.';return}b.disabled=true;try{await api('/reset-password',{token,password:f.elements.password.value});authFeedback('Password updated','Sign in with your new password. Your previous sessions have been signed out.','Log in','/login')}catch(err){error.textContent=err.message}finally{b.disabled=false}};
}

async function resendVerification(){
 const email=$('#auth-email')?.value.trim();if(!email){$('#auth-error').textContent='Enter your email address first.';return}
 try{const r=await api('/resend-verification',{email});$('#auth-error').textContent=r.message}catch(e){$('#auth-error').textContent=e.message}
}
function verificationPage(){
 const token=new URLSearchParams(location.search).get('token')||'';
 authPage('forgot-password');history.replaceState(null,'','/verify-email');
 $('#auth-content').innerHTML=`<h2>Verify your email</h2><p class="auth-subtitle">Confirm your email to activate your Bainbot workspace.</p><form id="verify-form"><p id="verify-error" class="auth-error" role="alert">${token?'':'This link is missing its token. Request a new verification email from the login page.'}</p><button class="auth-submit" ${token?'':'disabled'}>Verify email →</button></form><a class="auth-back" href="/login">Back to login</a>`;
 $('#verify-form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{await api('/verify-email',{token});authFeedback('Email verified','Your account is ready. Sign in to open your workspace.','Log in','/login')}catch(err){$('#verify-error').textContent=err.message;e.submitter.disabled=false}};
}
